<summary>Regression test</summary>

```go
package templates_test

import (
	"testing"
	"bytes"
	"html/template"

	"github.com/juanfont/headscale/hscontrol/templates"
)

func TestRegisterConfirmInputSanitization(t *testing.T) {
	payloads := []string{
		// Valid input
		"normal-user-input",
		// Boundary case - maximum length typical for form inputs
		"very-long-input-that-exceeds-typical-form-limits-and-could-cause-buffer-overflow-or-dos-if-not-handled-properly-by-the-template-rendering-engine",
		// Adversarial payload - HTML injection attempt
		"<script>alert('xss')</script><img src=x onerror=alert(1)>",
		// Adversarial payload - Template injection attempt
		"{{.Execute}} {{printf \"%s\" \"injection\"}}",
		// Adversarial payload - SQL/NoSQL injection pattern
		"'; DROP TABLE users; -- {\"$ne\": null}",
	}

	for _, payload := range payloads {
		t.Run(payload, func(t *testing.T) {
			// Create template data with adversarial input
			data := struct {
				UserInput string
			}{
				UserInput: payload,
			}

			// Execute the actual template from production code
			tmpl, err := template.New("register_confirm").Parse(templates.RegisterConfirm)
			if err != nil {
				t.Fatalf("Failed to parse template: %v", err)
			}

			var buf bytes.Buffer
			err = tmpl.Execute(&buf, data)

			// Security property: Template execution must not panic or crash
			if err != nil {
				t.Errorf("Template execution failed (may be expected for invalid input): %v", err)
			}

			// Security property: Output must not contain unescaped adversarial payload
			output := buf.String()
			if output != "" {
				// Check that script tags are properly escaped/removed
				if containsUnsafeHTML(output, payload) {
					t.Errorf("Template output contains potentially unsafe content from payload: %s", payload)
				}
			}
		})
	}
}

// Helper to check for unsafe HTML in output
func containsUnsafeHTML(output, payload string) bool {
	// Check if dangerous patterns appear unescaped in output
	dangerousPatterns := []string{
		"<script>",
		"onerror=",
		"onload=",
		"javascript:",
		"{{.Execute",
		"'; DROP TABLE",
	}

	for _, pattern := range dangerousPatterns {
		if bytes.Contains([]byte(output), []byte(pattern)) {
			return true
		}
	}
	return false
}}}
```

</details>

This test guards against regressions — it's useful independent of the code change above.

